  "revision_action": "keep",
  "supportive_card_ids": ["C04", "C116", "C108", "C118", "C119", "C102", "C148", "C142"],
  "contradictory_card_ids": ["C199", "C179", "C190", "C175", "C164"],
  "prediction_basis_card_ids": ["C04", "C116", "C108", "C118"],
  "claims": [
    {
      "claim": "The closest L1 structural analog with a direct human absolute-bioavailability measurement, a pyridine-sulfonyl piperazine pyrazolopyrimidinone, had 34% F in fasted healthy volunteers (C04), directly supporting F >= 20% for a sulfonyl-basic-amine lactam scaffold.",
      "card_ids": ["C04"]
    },
    {
      "claim": "L4 rat intestinal perfusion for the same sulfonyl-piperazine pyrazolopyrimidinone scaffold showed high effective permeability (jejunum 2.11 ± 0.28 and 1.66 ± 0.48 ×10^-5 cm/s; ileum 1.58 ± 0.17 ×10^-5 cm/s), indicating efficient intestinal absorption for this class (C116, C108, C118).",
      "card_ids": ["C116", "C108", "C118"]
    },
    {
      "claim": "Structurally, the query is the 1-oxo (lactam) analogue of fasudil; L6 shows fasudil is metabolized mainly by aldehyde oxidase with high intrinsic clearance (C250, C206, C228), but this clearance is measured for the parent and the query is the AO oxidation product, so it is not direct evidence of high presystemic loss for the query.",
      "card_ids": ["C250", "C206", "C228"]
    },
    {
      "claim": "Ripasudil's AO-mediated M1 formation (C240) similarly indicates that the 1-oxo metabolite is the product, not the substrate, of the main hepatic clearance pathway, reducing transferability of the parent's high clearance to the query.",
      "card_ids": ["C240"]
    },
    {
      "claim": "L5 provides only mechanistic efflux evidence for related compounds (vardenafil ER 7.27, piperazine analogue ER 441, predicted absorption 10-19%) without a direct low F for the query or closest scaffold, so it does not affirmatively establish F < 20% (C199, C179, C190).",
      "card_ids": ["C199", "C179", "C190"]
    },
    {
      "claim": "Related ionized quinolones have adequate solubility and permeability (ciprofloxacin 11.5 g/L and 6.3×10^-6 cm/s; norfloxacin 0.84-1.2 mg/mL; enoxacin very soluble at pH <4.5-5), supporting that strong ionization does not preclude F >= 20% (C119, C102, C148, C142).",
      "card_ids": ["C119", "C102", "C148", "C142"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C206", "C210", "C228", "C250", "C240", "C208", "C238"]
    }
  ],
  "evidence_gaps": [
    "No query-specific absolute oral bioavailability or matched oral/IV exposure measurement.",
    "No query-specific human PK, dose, formulation, or prandial condition.",
    "No direct metabolic stability or clearance measurement for the query itself; L6 measures fasudil/ripasudil, not the 1-oxo metabolite.",
    "No query-specific permeability, efflux, or intestinal metabolism data; L4/L5 evidence is analog-based.",
    "The query's identity as the AO metabolite of fasudil is inferred from structure, not explicitly stated in the records.",
    "Homopiperazine versus piperazine and isoquinolinone versus pyrazolopyrimidinone differences may alter transporter interactions and absorption."
  ],
  "decision_summary": "Predicted high because the closest direct-F L1 analog (C04) had 34% absolute oral bioavailability and L4 shows high intestinal permeability for the same sulfonyl-piperazine lactam scaffold; L6 fasudil/ripasudil hepatic-clearance records are mechanistically relevant but measure the parent compounds, and the query is the 1-oxo AO metabolite, so they do not affirmatively establish F < 20%; L5 efflux concerns remain mechanistic and analog-based. Confidence remains low."
}

